import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.DQvKz0xt.js";const m=JSON.parse('{"title":"状态机概览 (State Machine Overview) - Rive 编辑器","description":"状态机 (State Machines) 为你的动画增添智能逻辑。","frontmatter":{"title":"状态机概览 (State Machine Overview) - Rive 编辑器","description":"状态机 (State Machines) 为你的动画增添智能逻辑。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 状态机, 状态机概览"}]]},"headers":[],"relativePath":"editor/state-machine/overview.md","filePath":"editor/state-machine/overview.md","lastUpdated":1774838907000}'),s={name:"editor/state-machine/overview.md"};function n(o,e,p,h,c,d){return i(),a("div",null,[...e[0]||(e[0]=[r('<p>状态机 (State Machines)</p><h1 id="状态机概览-state-machine-overview" tabindex="-1">状态机概览 (State Machine Overview) <a class="header-anchor" href="#状态机概览-state-machine-overview" aria-label="Permalink to &quot;状态机概览 (State Machine Overview)&quot;">​</a></h1><p>为你的动画增添智能逻辑。</p><h2 id="​-概览" tabindex="-1"><a href="#overview">​</a> 概览 <a class="header-anchor" href="#​-概览" aria-label="Permalink to &quot;[​](#overview) 概览&quot;">​</a></h2><p>状态机是一种可视化地连接动画并定义驱动过渡逻辑的方式。它允许你构建可交互的动态图形，以便直接集成到产品、应用、游戏或网站中。 状态机为设计师和开发者之间创造了新的协作层级，让双方都可以在开发过程的深处进行迭代，无需繁复的交接。使用状态机需要设计师和动画师以开发者的思维方式思考，但以一种直观、可视化的方式呈现。 每个画板默认至少有一个状态机，但你可以根据需要创建更多。要创建新的状态机，请在动画列表中点击加号按钮，并选择 State Machine 选项。</p><h3 id="​-状态机的构成" tabindex="-1"><a href="#anatomy-of-a-state-machine">​</a> 状态机的构成 <a class="header-anchor" href="#​-状态机的构成" aria-label="Permalink to &quot;[​](#anatomy-of-a-state-machine) 状态机的构成&quot;">​</a></h3><p>一个基本的状态机由以下部分组成：图表 (Graph)、<a href="/docs/editor/state-machine/states">状态 (States)</a>、<a href="/docs/editor/state-machine/transitions">过渡 (Transitions)</a>、<a href="/docs/editor/state-machine/inputs">输入 (Inputs)</a> 和 <a href="/docs/editor/state-machine/layers">图层 (Layers)</a>。 <strong>图表 (Graph)</strong> 是你添加状态并连接过渡的空间。当在动画列表中选中状态机时，它会替代时间轴显示。 <img src="https://help.rive.app/images/307461c0-2006-4fdf-bdc3-61875d40f422.webp" alt="状态机图表"><strong>状态 (States)</strong> 本质上就是可以在状态机中播放的时间轴动画。它们通常代表你的动画内容所处的某种&quot;状态&quot;。例如，一个按钮通常有：Idle（静止）、Hovered（悬停）和 Clicked（点击）三种状态。 <img src="https://help.rive.app/images/image_1.png" alt="状态预览"> 定义好状态后，我们可以用 <strong>过渡 (Transitions)</strong> 将它们连接起来，创建一条状态机可以遵循的逻辑路径——这就像一张地图，指引状态机如何从一个动画切换到下一个。 <img src="https://help.rive.app/images/image_2.png" alt="创建过渡"></p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>弃用提示：</strong> 本节涉及旧版&quot;输入 (Inputs)&quot;系统。</p><ul><li><strong>新项目</strong>：请改用 <a href="/docs/editor/data-binding/overview">数据绑定 (Data Binding)</a>。</li><li><strong>现有项目</strong>：请尽早规划从 Inputs 迁移到 Data Binding。</li><li><strong>本内容仅为向后兼容提供支持。</strong></li></ul></div><p><strong>输入 (Inputs)</strong> 是控制状态机过渡的一种旧式工具。虽然仍可使用，但数据绑定 (Data Binding) 是当前的最佳实践，因为视图模型 (View Models) 更强大且在运行时更易控制。 输入是设计师与开发者之间的&quot;契约&quot;。设计师用它们作为过渡发生的条件规则，开发者在运行时对其进行操控。 <img src="https://help.rive.app/images/state-machine-overview-inputs.gif" alt="添加输入和条件"></p><p>最后，所有状态机至少有一个 <strong>图层 (Layer)</strong>。由于每个图层同一时间只能播放一个动画，如果需要混合不同动画或添加额外交互，我们可以添加多个图层。 <img src="https://help.rive.app/images/image_4.png" alt="多图层状态机"></p><p><a href="https://help.rive.app/editor/animate-mode/animating-draw-order" target="_blank" rel="noreferrer">绘制顺序动画</a><a href="/docs/editor/state-machine/states">状态 (States)</a></p>',11)])])}const g=t(s,[["render",n]]);export{m as __pageData,g as default};
